#include <iostream>
#include <cstdlib>
using namespace std;

int main() {
    srand(1);
    int target = rand() % 100 + 1;
    int guess = 0;
    int used = 0;

    cout << "本喵想了一个 1 到 100 的数，来猜猜看喵～" << endl;
    while (true) {
        cout << "猜一个数喵：";
        if (!(cin >> guess)) {
            cout << endl << "投喂口空了，本喵先收工喵" << endl;
            break;
        }
        used = used + 1;

        if (guess < target) {
            cout << "太小啦喵" << endl;
        } else if (guess > target) {
            cout << "太大啦喵" << endl;
        } else {
            cout << "猜中啦喵！一共猜了 " << used << " 次" << endl;
            break;
        }
    }
    return 0;
}
